/* Hide marketplace */
/*
ul[n-style="pso-dashboard-nav-horizontal"] > li:nth-child(2),
div.portal-nav-section-mobile > ul > li[n-style="pso-dashboard-nav-li"]:nth-child(2){
display: none;
}
*/

/* Hide route group path on self-reg */
body[n-style="pso-login-background"] application-navigation {
display: none;
}

/*Remove new customer login section*/
#loginForm p.slds-m-top--medium.portal-center-text {
display: none;
}


/*Hide make another selection button*/
#goBack {
display: none;
}

/*base font size*/
.slds body,
.slds:not(html) {
font-size: 16px;
}

/*loading background color*/
.portal-loader-overlay {
background-color: rgba(255, 255, 255, .64);
transition: .3s;
}

.portal-loader-overlay .portal-loader-message {
top: 40%;
}

/*hide oa icon*/
.slds span[n-style="pso-section-icon"] {
display: none;
}

/*remove oa section background*/
.portal-form-container[n-style="pso-section"] {
background-color: #fff;
box-shadow: none;
margin-top: 0;
}

/*removing additional space below header text*/
[n-style="pso-oa-topbar"] .slds-grid.slds-wrap.slds-m-top--medium.slds-p-bottom--large {
display: none;
}

/*show subheader text in mobile*/
.slds [n-style="pso-application-body-subheader"] {
display: block !important;
}

/*removing shadow from multi-object cards*/
.slds .multi-object-form-edit-card {
box-shadow: none;
}

/*input and select hover, active, and placeholder*/
.slds .slds-input:hover,
.slds .slds-input:focus,
.slds .slds-select:hover,
.slds .slds-select:focus,
.portal-input-group:hover .portal-input-group-addon,
.portal-input-group:focus .portal-input-group-addon {
border-bottom-color: #1589EE !important;
}

.portal-input-group .portal-input-group-addon {
transition: .3s;
}

.slds .slds-input.ng-not-empty,
.slds .slds-select.ng-not-empty,
.slds nds-input-datepicker.ng-not-empty .slds-input,
.slds nds-input-number.ng-not-empty .slds-input,
.slds nds-input-number.ng-not-empty .portal-input-group .portal-input-group-addon,
nds-input-long-text.ng-not-empty .slds-textarea,
nds-input-long-text .slds-textarea:hover,
nds-input-long-text .slds-textarea:active {
border-bottom-color: #1589EE !important;
}

.slds .slds-input::-webkit-input-placeholder {
color: #706E6B;
}

/*Lined Input*/
.slds .slds-form-element__control {}

/*left padding for portal section subheaders*/
.slds .h4.slds-form-element__label[ng-bind="section.portalSubheaderText"] {
padding-left: 12px;
}

/*make button groups smaller width to provide button affordance*/
.portal-button-group [n-style="pso-button-secondary"] {
background-color: rgba(216, 237, 255, 0.14) !important;
border-bottom: 2px solid #d8dde6 !important;
border-radius: 8px 8px 0 0;
}

.slds .slds-wizard {
max-width: 600px;
margin: 0 auto;
}

div.portal-wrapper {
background: #fff;
border-bottom: 1px solid #d8dde6;
}

.slds .slds-datepicker__filter .slds-select_container:after,
.slds .slds-datepicker__filter .slds-select_container:before {
height: inherit;
}


/*fixing padding on buttons made with a tags*/
.slds a.slds-button {
padding-top: 8px;
}

/*fixing review and submit spacing*/
div.portal-review-section .slds-grid .slds-form-element__static {
font-size: 18px;
line-height: 20px;
margin-bottom: 16px;
font-weight: 300;
}

/*submit button*/
#submitOnlineForm {
margin-top: 64px;
height: 64px !important;
}

/*align collateral icon on review and submit to the top*/
.slds .portal-collateral-review-item {
align-items: flex-start;
}

/*fix dashboard header height*/
.slds .portal-dashboard-hero-content {
min-height: inherit;
}

/*hide your product icons to reduce visual noise*/
.slds .portal-your-products-header .slds-p-right--x-small {
display: none;
transparency: 1;
}

/*keeping selected offers card from jumping*/
.slds .offers-card {
border-top: 8px solid #fff;
}

/*making product cards full width after hiding icons*/
.slds-grid.portal-your-products-header .slds-col.slds-size--7-of-8 {
width: 100%;
}

/*separating to-do list from additional products and cards*/
.todo-list-wrapper {
margin-bottom: 128px;
}

/*Make Checkmark Large*/
.slds .slds-checkbox [type=checkbox]:checked + .slds-checkbox--faux:after,
.slds .slds-checkbox [type=checkbox]:checked ~ .slds-checkbox--faux:after {
height: 7px;
width: 14px
}

/*Left align to-do list headers*/
.slds .todo-list-wrapper h2.slds-text-heading--small {
text-align: left;
}

/*fix modal not scrolling on mobile, mainly for review and accept functionality*/
.slds .slds-modal__content {
overflow: scroll;
}

/*tile header background color*/
.slds .portal-tile-header {
background-color: transparent;
padding: 12px 0 12px 0;
}

/*center tile when in bottom center position*/
.slds .portal-center-bottom-tile {
max-width: 664px;
margin: 0 auto;
}

/*Fixing your products card width on mobile*/
.your-products-card-wrapper {
min-width: auto;
}

/*Questionnaire questions single column*/
.portal-questionnaire-container .slds-scope .slds-size_12-of-12{
width: 100% !important;
}

/*----------REVIEW AND SUBMIT STYLING BELOW------------*/

/*review and submit section headers and spacing*/
[n-style="pso-review-section"] [n-style="pso-smallheader"] {
margin-top: 16px !important;
padding-left: 0 !important;
}

[n-style="pso-review-section"] .h4.slds-form-element__label[ng-bind="section.portalSubheaderText"] {
padding-left: 0 !important;
}

[n-style="pso-review-section"] .slds-m-top--small {
margin-top: 0;
}

/*----------BUSINESS OWNER CARDS BELOW------------*/

/*bold business name*/
.slds .portal-owner-card .slds-media__body p:first-of-type {
font-weight: bold
}

/*transparent card background*/
.slds .portal-owner-card .slds-card {
background-color: transparent;
border: none;
}

/*sizing*/
.slds .portal-owner-card .slds-media {
display: block
}

/*remove box shadow and fix border*/
.slds .portal-owner-card div.portal-selected-grid-cell {
box-shadow: none;
border-left: 4px #0176D3 solid;
}

.slds .portal-owner-card .card-bottom-active-button {
box-shadow: none;
}

.slds .portal-owner-card .card-bottom-button {
border: none !important;
text-align: left;
}

/*hide edit buttons*/
.portal-owner-card .slds-media__body button.slds-button.slds-button--neutral.slds-float--right {
display: none;
}

/*----------ACCOUNT OPTIONS STYLING BELOW------------*/
.slds div.portal-detail-row:hover {
box-shadow: none;
}

.slds div.portal-detail-row {
box-shadow: none;
}

/*----------MOBILE STYLING BELOW------------*/

@media only screen and (max-width: 1024px) {
.slds [n-style="pso-dashboard-topbar"] {
max-width: 100% !important;
margin: 0px auto !important;
padding: 32px 24px !important;
}

/*mobile header text sizing*/
.slds [n-style="pso-application-body-header"], .slds [n-style="pso-dashboard-topbar-header"] {
font-size: 28px !important;
}
.slds [n-style="pso-smallheader"], .slds [n-style="pso-form-label"] {
margin-left: 0;
padding-left: 0;
}

/*mobile suggested product card buttons*/
[n-style="pso-detail-card"] .slds-size--1-of-1.slds-large-size--3-of-12.slds-align-middle.slds-text-align--center {
padding: 0 32px 16px 32px
}

/*left align h1 on mobile*/
[n-style="pso-oa-topbar"]{
padding-left: 0 !important;
}

/*shrinking subheader text size on mobile*/
[n-style="pso-application-body-subheader"] {
font-size: 16px !important;
}
}

