.slds .slds-input {
    background-color: #fff;
    color: #313645;
    border: 1px solid #A6ABC5;
    border-radius: 5px;
    width: 100%;
    transition: border .1s linear,background-color .1s linear;
    display: inline-block;
    padding: 0 16px 0 12px;
    line-height: 30px;
    height: 48px;
    font-weight: 400;
    font-size: 16px;
    line-height: 24px;
}

.slds .slds-input:active,.slds .slds-input:focus {
    outline: 0;
    border: 2px solid #4965CD;
    background-color: #fff;
