    line-height: 1.5;
    margin-right: 12px;
    margin-bottom: 12px;
    font-weight: 600;
    font-size: 16px;
    line-height: 26px;
}

.slds .slds-form-element__label:empty {
    margin: 0
}
.slds .slds-input::placeholder {
    font-weight: 400;
    font-size: 16px;
    line-height: 24px;
    color: #A6ABC5;
  }

/*Combo box*/
.slds .slds-select {
    background-color: #fff;
    color: #313645;
    border: 1px solid #A6ABC5;
    border-radius: 5px;
    width: 100%;
    transition: border .1s linear,background-color .1s linear;
    display: inline-block;
    padding: 0 16px 0 12px;
    line-height: 30px;
    height: 48px;
    font-weight: 400;
    font-size: 16px;
    line-height: 24px;
    background-repeat: no-repeat;
    background-position: right;
    background-size: 48px;
    background-image: url(data:image/png;base64,);

}

.slds .slds-select::placeholder {
    font-weight: 400;
    font-size: 16px;
    line-height: 24px;
    color: #A6ABC5;
}

.slds .slds-select:active,.slds .slds-select:focus {
    outline: 0;
    border: 2px solid #4965CD;
    background-color: #fff;
    box-shadow: 0 0 0px #fff
}

.slds .slds-select_container {
    position: relative
}

.slds .slds-select_container .slds-select {
    -moz-appearance: none;
    -webkit-appearance: none;
    padding-left: 8px;
    padding-right: 24px;
}

.slds .slds-select_container .slds-select::-ms-expand {
    display: none
}

.slds .slds-select_container:after,.slds .slds-select_container:before {
    position: absolute;
    left: 25%;
    right: 25%;
    top: 37.5%;
    bottom: 37.5%;    
    border: 2px solid #fff;
    display:none
}

.slds .slds-select_container:before {
    border-bottom: 5px solid #fff;
    top: calc((28px / 2) - 6px);
    display:none
}

.slds .slds-select_container:after {
    border-top: 5px solid #fff;
    bottom: calc((28px / 2) - 6px);
