/*Checkbox*/
/* Check box */

.slds .slds-checkbox {
    display: inline-block;
  }

  .slds .slds-checkbox .slds-checkbox--faux {
    top: 0;
    left: 0;
    height: 25px;
    width: 25px;
    background-color: #fff;
    border-radius: 5px;
  }

  .slds .slds-checkbox .slds-checkbox--faux:hover,
  .slds .slds-checkbox .slds-checkbox--faux:active {
    top: 0;
    left: 0;
    height: 25px;
    width: 25px;
    background-color: #fff;
  }

  .slds .slds-checkbox .slds-checkbox--faux:after {
    background-color: #24386C;
  }

  .slds .slds-checkbox .slds-form-element__label {
    display: inline;
    vertical-align: middle;
    font-size: 13px;
  }

  .slds .slds-checkbox [type="checkbox"] {
    width: 1px;
    height: 1px;
    border: 0;
    clip: rect(0 0 0 0);
    margin: -1px;
    overflow: hidden;
    padding: 0;
  }

  .slds .slds-checkbox [type="checkbox"]:checked + .slds-checkbox--faux:after,
  .slds .slds-checkbox [type="checkbox"]:checked ~ .slds-checkbox--faux:after {
    display: block;
    content: "";
    height: 5px;
    width: 10px;
    top: 50%;
    left: 50%;
    transform: translate3d(-50%, -50%, 0) rotate(-45deg);
    border-bottom: 2px solid #fff;
    border-left: 2px solid #fff;
    background-color: #24386C;
  }

  .slds .slds-form-element .slds-checkbox[type="checkbox"]:checked + .slds-checkbox--faux:after,
  .slds .slds-form-element .slds-checkbox[type="checkbox"]:checked ~ .slds-checkbox--faux:after {
    display: block;
    content: "";
    height: 5px;
    width: 10px;
    top: 50%;
    left: 50%;
    transform: translate3d(-50%, -50%, 0) rotate(-45deg);
    border-bottom: 2px solid #fff;
    border-left: 2px solid #fff;
    background-color: #24386C;
  }

  .slds .slds-form-element .slds-checkbox[type="checkbox"] + .slds-checkbox--faux,
  .slds .slds-form-element .slds-checkbox[type="checkbox"] ~ .slds-checkbox--faux {
    margin-right: 8px;
  }

  .slds .slds-checkbox [type="checkbox"]:checked > .slds-checkbox--faux,
  .slds .slds-checkbox [type="checkbox"]:checked ~ .slds-checkbox--faux {
    background-color: #24386C;
  }

  .slds .slds-checkbox [type="checkbox"]:focus + .slds-checkbox--faux,
  .slds .slds-checkbox [type="checkbox"]:focus ~ .slds-checkbox--faux {
    content: "";
    box-shadow: 0 0 0px #fff;
  }

  .slds .slds-checkbox [type="checkbox"]:focus:checked > .slds-checkbox--faux,
  .slds .slds-checkbox [type="checkbox"]:focus:checked ~ .slds-checkbox--faux {
    background-color: #24386C;
  }

  .slds .slds-checkbox [type="checkbox"][disabled] + .slds-checkbox--faux,
  .slds .slds-checkbox [type="checkbox"][disabled] ~ .slds-checkbox--faux {
    background-color: #e0e5ee;
    border-color: #a8b7c7;
  }

  .slds .slds-checkbox [type="checkbox"][disabled] + .slds-checkbox--faux:after,
  .slds .slds-checkbox [type="checkbox"][disabled] ~ .slds-checkbox--faux:after {
    border-color: #fff;
  }

  .slds .slds-has-error .slds-checkbox [type="checkbox"] + .slds-checkbox--faux,
  .slds .slds-has-error .slds-checkbox [type="checkbox"] ~ .slds-checkbox--faux {
    border-color: #c23934;
    border-width: 2px;
  }

  .slds
    .slds-has-error
    .slds-checkbox
    [type="checkbox"]:checked
    + .slds-checkbox--faux,
  .slds
    .slds-has-error
    .slds-checkbox
    [type="checkbox"]:checked
    ~ .slds-checkbox--faux {
    border-color: #c23934;
    background-color: #fff;
  }

  .slds
    .slds-has-error
    .slds-checkbox
    [type="checkbox"]:checked
    + .slds-checkbox--faux:after,
  .slds
    .slds-has-error
    .slds-checkbox
    [type="checkbox"]:checked
    ~ .slds-checkbox--faux:after {
    border-color: #d4504c;
  }

  .slds
    .slds-form-element
    .slds-checkbox
    [type="checkbox"]
    + .slds-checkbox--faux,
  .slds
    .slds-form-element
